    dict(key='28-class-1', kind='code', title='Model — checking the picture',
         body='// Model: elements in zones, flows, and trust boundaries\nif (crosses(f) && boundaryOf(f).isEmpty()) {\n    problems.add(f.id() + " goes from " + zoneOf(f.from())\n            + " to " + zoneOf(f.to()) + ", skipping a boundary");',
         narration='A flow that changes zone must cross exactly one drawn boundary. [[slnc 300]] If none separates its two zones, the picture is wrong, and the threats on the missing boundary would be hidden.'),
